// Metrics require observed events. Labels and status modification times are not message timestamps.
function replyMetrics({conversations,from,to,workspaceId}){
 const parse=x=>{const n=Date.parse(x||'');return Number.isFinite(n)?n:null};
 const lo=parse(from),hi=parse(to);if(lo===null||hi===null||hi<=lo)throw Error('Invalid reporting interval');
 const median=a=>{const b=[...a].sort((x,y)=>x-y);return b.length?(b[Math.floor((b.length-1)/2)]+b[Math.ceil((b.length-1)/2)])/2:null};
 const avg=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
 const unique=new Map(), issues=[];
 for(const c of conversations){
  if(c.testOnly||c.workspaceId!==workspaceId)continue;
  if(!c.id){issues.push('Missing conversation identity');continue;}
  if(unique.has(c.id)){issues.push('Duplicate conversation excluded: '+c.id);continue;}unique.set(c.id,c);
 }
 const speeds=[],touches=[],bookHours=[];let inbound=0,positive=0,booked=0,positiveBooked=0,sent=0,aiSent=0,humanSent=0,unknownActor=0,unanswered=0,unknownResponse=0,unknownBooking=0;
 for(const c of unique.values()){
  const ids=new Set(),messages=[];
  for(const m of c.messages||[]){
   if(m.testOnly||!m.id||ids.has(m.id))continue;ids.add(m.id);
   const at=parse(m.at);if(at===null||at>=hi)continue;
   if(m.direction==='inbound'&&m.automated!==true)messages.push({...m,at});
   if(m.direction==='outbound'&&m.status==='sent')messages.push({...m,at});
  }
  messages.sort((a,b)=>a.at-b.at);
  const first=messages.find(m=>m.direction==='inbound');
  // Cohort is conversations whose first known human inbound occurred in the interval.
  if(!first||first.at<lo||!c.firstInboundConfirmed)continue;
  inbound++;if(c.positive===true){positive++;}
  const responses=messages.filter(m=>m.direction==='outbound'&&m.at>=first.at);
  for(const m of responses){sent++;if(m.actor==='AI')aiSent++;else if(m.actor==='Human')humanSent++;else unknownActor++;}
  const response=responses[0];
  if(response&&c.historyComplete){speeds.push((response.at-first.at)/60000);}
  else if(!response&&c.historyComplete)unanswered++;else unknownResponse++;
  const booking=c.booking;const bookedAt=parse(booking?.createdAt);
  const confirmed=booking?.confirmed===true&&booking.id&&bookedAt!==null&&bookedAt>=first.at&&bookedAt<hi&&booking.cancelled!==true;
  if(confirmed){booked++;if(c.positive===true)positiveBooked++;if(c.historyComplete){touches.push(responses.filter(m=>m.at<=bookedAt).length);if(response&&response.at<=bookedAt)bookHours.push((bookedAt-response.at)/3600000);}}
  else if(c.wonLabel||c.bookingCoverageComplete!==true)unknownBooking++;
 }
 return {workspaceId,from,to,cohort:'First confirmed human inbound in range; outcomes observed before range end',conversations:inbound,positiveConversations:positive,confirmedMeetings:booked,positiveMeetings:positiveBooked,repliesSent:sent,aiRepliesSent:aiSent,humanRepliesSent:humanSent,unknownResponderReplies:unknownActor,avgFirstResponseMinutes:avg(speeds),medianFirstResponseMinutes:median(speeds),measuredFirstResponses:speeds.length,unansweredConversations:unanswered,unknownResponseConversations:unknownResponse,avgTouchesToMeeting:avg(touches),measuredMeetingTouches:touches.length,avgFirstResponseToBookingHours:avg(bookHours),measuredBookingResponseTimes:bookHours.length,replyToMeetingRate:inbound?booked/inbound:null,positiveToMeetingRate:positive?positiveBooked/positive:null,unverifiedBookingConversations:unknownBooking,coverage:unknownResponse||unknownBooking||issues.length?'Partial':inbound?'Complete':'Insufficient',issues};
}

function buildSnapshots({conversations,workspaceNames={},now=Date.now(),historicalCoverageComplete=false}){
 const day=stamp=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(stamp));const groups=new Map();
 for(const c of new Map(conversations.map(c=>[c.workspaceId+'|'+c.id,c])).values()){if(!c.valid||!c.firstInboundConfirmed)continue;const first=c.messages.find(m=>m.direction==='inbound');if(!first)continue;const date=day(first.at),key=c.workspaceId+'|'+date; if(Date.parse(first.at)<now-90*86400000)continue;if(!groups.has(key))groups.set(key,{workspaceId:c.workspaceId,date,rows:[]});groups.get(key).rows.push(c);}
 const records=[];
 // A responder cohort is owned by its first confirmed reply. Unknown authors stay in All only.
 const cohorts=[];
 for(const g of groups.values()){
  cohorts.push({...g,responder:'All'});
  for(const actor of ['AI','Human']){
   const rows=g.rows.filter(c=>{const first=c.messages.find(m=>m.direction==='inbound');const response=c.messages.find(m=>m.direction==='outbound'&&m.status==='sent'&&Date.parse(m.at)>=Date.parse(first?.at));return c.historyComplete&&response?.actor===actor;});
   // Include empty segment snapshots so corrected attribution can clear stale totals.
   cohorts.push({...g,rows,responder:actor});
  }
 }
 for(const g of cohorts){
  const m=replyMetrics({conversations:g.rows,workspaceId:g.workspaceId,from:new Date(g.rows.length?Math.min(...g.rows.flatMap(c=>c.messages.filter(m=>m.direction==='inbound').map(m=>Date.parse(m.at)))):now-90*86400000).toISOString(),to:new Date(now+1).toISOString()});
  // Cohort membership is fixed by first inbound date; outcomes are observed up to calculation time.
  const bookingKnown=m.unverifiedBookingConversations===0;
  records.push({fields:{'Snapshot Key':'v2|'+g.workspaceId+'|'+g.date+'|'+g.responder,'Date':g.date,'Workspace Name':workspaceNames[g.workspaceId]||g.workspaceId,'Workspace Record ID':g.workspaceId,'Responder Type':g.responder,'Inbound Replies':m.conversations,'Unique Leads':new Set(g.rows.map(c=>c.leadKey).filter(Boolean)).size,'Positive Replies':m.positiveConversations,'Meetings Booked':bookingKnown?m.confirmedMeetings:null,'Positive Meetings Booked':bookingKnown?m.positiveMeetings:null,'Unknown Responder Replies':m.unknownResponderReplies,'Measured Meeting Touches':m.measuredMeetingTouches,'Measured Booking Response Times':m.measuredBookingResponseTimes,'AI Replies Sent':m.aiRepliesSent,'Human Replies Sent':m.humanRepliesSent,'Unanswered Replies':m.unansweredConversations,'Human Review Count':g.rows.filter(c=>c.humanReview===true).length,'Needs Changes Count':g.rows.filter(c=>c.needsChanges===true).length,'AI Errors':g.rows.filter(c=>c.hasError===true).length,'Avg First Response Minutes':m.avgFirstResponseMinutes,'Avg Touchpoints to Meeting':m.avgTouchesToMeeting,'Avg First Response to Booked Hours':m.avgFirstResponseToBookingHours,'Responses Within 15 Minutes':g.rows.filter(c=>{const a=c.messages.find(m=>m.direction==='inbound'),b=c.messages.find(m=>m.direction==='outbound'&&Date.parse(m.at)>=Date.parse(a?.at));return a&&b&&c.historyComplete&&(Date.parse(b.at)-Date.parse(a.at))/60000<=15}).length,'Measured First Responses':m.measuredFirstResponses,'Data Coverage':historicalCoverageComplete&&m.coverage==='Complete'&&m.unknownResponderReplies===0?'Complete':g.rows.length?'Partial':'Insufficient','Source Notes':'Provider-backed first-human-reply cohort (America/New_York date). Segment '+g.responder+' is based on first confirmed responder; All includes unknown and unanswered. Outcomes through '+new Date(now).toISOString()+'. '+m.repliesSent+' confirmed sent replies; '+m.unknownResponderReplies+' have no verified author attribution. '+m.measuredFirstResponses+' measured first responses. Booking counts and conversion remain blank until calendar booking evidence is available. Historical import coverage may be incomplete.','Last Calculated At':new Date(now).toISOString()}});
 }
 return records;
}

