// Normalize observed provider data only. No business outcomes are inferred from a label.
function normalizeThread({response,record,workspaceId,events=[],now=Date.now()}){
 const f=record.fields||record,root=response?.data||response;
 const fail=reason=>({valid:false,recordId:record.id,workspaceId,reason});
 if(response?.error||!root?.current_reply||String(root.current_reply.id)!==String(f.reply_message_id))return fail('Provider reply identity mismatch or unavailable');
 if(!Array.isArray(root.older_messages)||!Array.isArray(root.newer_messages)||response.meta?.next_page_url||response.links?.next||root.next_page_url)return fail('Incomplete provider conversation');
 const messages=[],seen=new Set();let invalidTime=false;
 for(const m of [...root.older_messages,root.current_reply,...root.newer_messages]){
  if(!m.id||seen.has(String(m.id)))continue;seen.add(String(m.id));
  const folder=String(m.folder||'').toLowerCase();
  if(['outbox','draft','drafts','queued'].includes(folder))continue;
  const outbound=['sent','delivered'].includes(folder)&&String(m.type||'').toLowerCase()==='outgoing email';
  const inbound=['inbox','spam','archive','archived','trash'].includes(folder)&&m.automated_reply===false;
  if(!outbound&&!inbound)continue;
  const stamp=outbound?(m.sent_at||m.date_sent||m.date_received):m.date_received;
  const at=Date.parse(stamp||'');if(!Number.isFinite(at)||at>now+60000){invalidTime=true;continue;}
  const matching=events.filter(e=>e.workspaceId===workspaceId&&String(e.providerMessageId)===String(m.id)&&e.type==='Sent');
  const actors=new Set(matching.map(e=>e.actor).filter(a=>['AI','Human'].includes(a)));
  messages.push({id:String(m.id),at:new Date(at).toISOString(),direction:outbound?'outbound':'inbound',status:outbound?'sent':undefined,actor:actors.size===1?[...actors][0]:undefined,automated:false});
 }
 messages.sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));
 const first=messages.find(m=>m.direction==='inbound');if(!first)return fail('No confirmed human inbound');
 const bookingAt=Date.parse(f['Meeting Booked At']||'');
 return {valid:true,id:String(first.id),recordId:record.id,workspaceId,leadKey:String(f['Leads Email']||'').trim().toLowerCase(),humanReview:['Needs Approval','Approved'].includes(String(f['Dulcy Reply Agent State']||'')),needsChanges:/needs changes/i.test(String(f['Dulcy Reply Agent Human Action']||'')),hasError:Boolean(f['Dulcy Reply Agent Last Error']),messages,firstInboundConfirmed:!invalidTime,historyComplete:!invalidTime,positive:root.current_reply.interested===true,wonLabel:String(f['Opportunity Status']?.name||f['Opportunity Status']||'').toUpperCase()==='WON',bookingCoverageComplete:false,booking:Number.isFinite(bookingAt)&&f['Calendar Booking ID']?{id:f['Calendar Booking ID'],createdAt:new Date(bookingAt).toISOString(),confirmed:true,cancelled:f['Meeting Cancelled']===true}:null,observedAt:new Date(now).toISOString()};
}

const sources=$('Prepare Provider Metrics Reads').all();const events=$('Get Recent Reply Events').all().map(i=>i.json).flatMap(r=>{const f=r.fields||r;if(f['Event Type']!=='Sent')return [];let p;try{p=JSON.parse(f['Payload JSON']||'{}')}catch{return [];}const m=p.data?.reply||p.data||{};return m.id?[{workspaceId:f['Workspace Record ID'],providerMessageId:String(m.id),actor:f.Actor,type:'Sent'}]:[];});const results=$input.all().flatMap((item,i)=>sources[i]?.json.skip?[]:[normalizeThread({...sources[i].json,response:item.json,events})]);return [{json:{facts:[...new Map(results.filter(r=>r.valid).map(r=>[r.workspaceId+'|'+r.id,r])).values()],failures:results.filter(r=>!r.valid).map(r=>({recordId:r.recordId,reason:r.reason}))}}];
